CREATE TABLE kliyan (
  id SERIAL PRIMARY KEY,
  non VARCHAR(100) NOT NULL,
  imèl VARCHAR(150) UNIQUE NOT NULL
);

CREATE TABLE kòmand (
  id SERIAL PRIMARY KEY,
  kliyan_id INTEGER NOT NULL REFERENCES kliyan(id) ON DELETE CASCADE,
  total NUMERIC(10,2) NOT NULL,
  dat_kòmand DATE DEFAULT CURRENT_DATE
);

CREATE FUNCTION nivo_kliyan(total NUMERIC)
RETURNS TEXT AS $$
BEGIN
  IF total >= 10000 THEN RETURN 'VIP';
  ELSIF total >= 3000 THEN RETURN 'Fidèl';
  ELSE RETURN 'Nouvo';
  END IF;
END;
$$ LANGUAGE plpgsql;

SELECT non, nivo_kliyan(total_achte) FROM kliyan;

CREATE VIEW fakti AS
SELECT k.non AS kliyan, c.id, c.total, c.dat_kòmand
FROM kliyan k JOIN kòmand c ON c.kliyan_id = k.id;

CREATE MATERIALIZED VIEW lavant_mwa AS
SELECT date_trunc('month', dat_kòmand) AS mwa, SUM(total)
FROM kòmand GROUP BY 1;

