CREATE TABLE pwodwi (id SERIAL PRIMARY KEY, info JSONB);
INSERT INTO pwodwi (info) VALUES
  ('{"non": "Chemiz", "koulè": "wouj", "stok": 10}'),
  ('{"non": "Pantalon", "koulè": "ble", "stok": 4}');

SELECT info->>'non' AS non
FROM pwodwi
WHERE info @> '{"koulè": "wouj"}';

CREATE TABLE lavant (
  id SERIAL,
  dat DATE NOT NULL,
  total NUMERIC(10,2)
) PARTITION BY RANGE (dat);

CREATE TABLE lavant_2026_10 PARTITION OF lavant
  FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');
CREATE TABLE lavant_2026_11 PARTITION OF lavant
  FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');

